"""Pixel and state checks for real crop growth, resident gait and water holes."""
from pathlib import Path
from playwright.sync_api import sync_playwright
import json, os, subprocess
ROOT=Path(__file__).resolve().parents[2]
OUT=ROOT/'work/detail-qa';OUT.mkdir(parents=True,exist_ok=True)
build="""import{build}from'esbuild';await build({stdin:{contents:"export {drawCropField,drawResident} from './src/pangea/cityDetail';export {paintLocalWater} from './src/pangea/landscape';",resolveDir:process.cwd(),loader:'ts'},bundle:true,format:'iife',globalName:'Detail',outfile:process.argv[1],alias:{'@':process.cwd()+'/src'}});"""
subprocess.run(['node','--input-type=module','-e',build,str(OUT/'detail.js')],cwd=ROOT,check=True)
report={'checks':[],'errors':[]}
with sync_playwright() as p:
 browser=p.chromium.launch(executable_path=os.environ.get('CHROMIUM_PATH','/usr/bin/chromium'),headless=True,args=['--no-sandbox'])
 page=browser.new_page(viewport={'width':900,'height':660},reduced_motion='reduce');page.on('pageerror',lambda e:report['errors'].append(str(e)))
 page.set_content('<style>body{margin:0;background:#202c27;color:#e6d8b4;font:16px Georgia}h1{font-size:24px;margin:22px}canvas{width:900px;height:600px}</style><h1>PANGEA · cultivated land / actual crop states</h1><canvas width="1800" height="1200"></canvas>');page.add_script_tag(content=(OUT/'detail.js').read_text())
 crops=page.evaluate('''()=>{const canvas=document.querySelector('canvas'),c=canvas.getContext('2d');c.scale(2,2);const states=[{sown:false,growth:45,yield:0},{sown:true,growth:45,yield:0},{sown:true,growth:80,yield:50}],labels=['Fallow / not sown','Growing','Ready to harvest'];const signatures=[],original=[];for(let row=0;row<3;row++)for(let col=0;col<3;col++){const type=['farm','wheatfield','flaxfield'][row],b={type,crop:states[col]},before=JSON.stringify(b);Detail.drawCropField(c,b,150+col*300,115+row*195);c.fillStyle='#dfcfaa';c.textAlign='center';c.font='16px Georgia';c.fillText(type.replace('field','')+' · '+labels[col],150+col*300,188+row*195);original.push(before===JSON.stringify(b));}const test=document.createElement('canvas');test.width=230;test.height=150;const t=test.getContext('2d'),render=(type,crop)=>{t.clearRect(0,0,230,150);Detail.drawCropField(t,{type,crop},115,80);return test.toDataURL()};for(const type of ['farm','wheatfield','flaxfield'])signatures.push(states.map(crop=>render(type,crop)));return {unchanged:original.every(Boolean),fallowIgnoresStaleGrowth:render('farm',states[0])===render('farm',{sown:false,growth:0,yield:0}),growthVisible:signatures.every(a=>new Set(a).size===3),matureTypesDistinct:new Set(signatures.map(a=>a[2])).size===3};}''')
 assert all(crops.values()),crops;report['checks'].append({'crops':crops});page.screenshot(path=str(OUT/'crop-states.png'))
 residents=page.evaluate('''()=>{const canvas=document.createElement('canvas');canvas.width=60;canvas.height=60;const c=canvas.getContext('2d'),person={id:1,color:'#8bbab3',ageDays:7000,x:2,y:2,task:{stage:'walk',path:[{x:3,y:2}],index:0}},before=JSON.stringify(person);const render=(time,reduced)=>{c.clearRect(0,0,60,60);Detail.drawResident(c,person,30,40,time,reduced);return canvas.toDataURL()};const animated=render(0,false)!==render(.1,false),reduced=render(0,true)===render(.1,true),unchanged=before===JSON.stringify(person),front=render(0,true);person.task.path=[{x:1,y:2}];const direction=front!==render(0,true);person.task.stage='work';return {animated,reduced,direction,unchanged,stationary:render(0,false)===render(.1,false)};}''')
 assert all(residents.values()),residents;report['checks'].append({'residents':residents})
 water=page.evaluate('''()=>{const canvas=document.createElement('canvas');canvas.width=520;canvas.height=520;const c=canvas.getContext('2d'),tiles=Array.from({length:400},(_,i)=>({type:(i%20>=7&&i%20<=12&&Math.floor(i/20)>=7&&Math.floor(i/20)<=12)?'grass':'water'}));tiles[3*20+3].type='ford';const before=JSON.stringify(tiles);c.fillStyle='#66804d';c.fillRect(0,0,520,520);Detail.paintLocalWater(c,{nx:20,ny:20,seed:41,tiles,project:(x,y)=>({x:x*24+20,y:y*24+20})});const pixel=(x,y)=>Array.from(c.getImageData(x,y,1,1).data),dry=pixel(260,260),wet=pixel(140,140),ford=pixel(92,92);return {unchanged:before===JSON.stringify(tiles),dryIsland:dry[0]===102&&dry[1]===128&&dry[2]===77,waterFilled:JSON.stringify(dry)!==JSON.stringify(wet),fordStone:ford[0]>wet[0]&&ford[1]>wet[1]};}''')
 assert all(water.values()),water;report['checks'].append({'water':water});assert not report['errors'];browser.close()
(OUT/'report.json').write_text(json.dumps(report,indent=2)+'\n');print(json.dumps(report,indent=2))
